GLOBAL.STRINGS.CHARACTERS.WAGSTAFF.DESCRIBE.ROTTENEGG = "Smells sulfuric. Excellent!"
GLOBAL.STRINGS.CHARACTERS.WAGSTAFF.DESCRIBE.ROUND_DOOR = "Cordial."
