GLOBAL.STRINGS.CHARACTERS.WAXWELL.DESCRIBE.CACTUS_MEAT_COOKED = "Cactus comestible."
GLOBAL.STRINGS.CHARACTERS.WAXWELL.DESCRIBE.CALIFORNIAROLL = "We meet again, crabbit."
