GLOBAL.STRINGS.CHARACTERS.WAXWELL.DESCRIBE.LEIF = "Disgusting creature!"
GLOBAL.STRINGS.CHARACTERS.WAXWELL.DESCRIBE.LEIF_SPARSE = "Disgusting creature!"
GLOBAL.STRINGS.CHARACTERS.WAXWELL.DESCRIBE.LICHEN = "This fungus survived the downfall."
GLOBAL.STRINGS.CHARACTERS.WAXWELL.DESCRIBE.LIF_PLANT = "I do still prefer roses."
