GLOBAL.STRINGS.CHARACTERS.WENDY.DESCRIBE.TURF_DEEPRAINFOREST_NOCANOPY = "Some ground."
GLOBAL.STRINGS.CHARACTERS.WENDY.DESCRIBE.TURF_DESER_DIRT = "It's just ground."
GLOBAL.STRINGS.CHARACTERS.WENDY.DESCRIBE.TURF_DIRT = "Some ground."
GLOBAL.STRINGS.CHARACTERS.WENDY.DESCRIBE.TURF_FIELDS = "Some ground."
GLOBAL.STRINGS.CHARACTERS.WENDY.DESCRIBE.TURF_FOREST = "Some ground."
GLOBAL.STRINGS.CHARACTERS.WENDY.DESCRIBE.TURF_FOUNDATION = "Some ground."
